steps.expression:
// The page size is a setting, not a constant: it belongs in the
// configuration Flow so every consumer agrees on it.
var size = Parameters.config.pageSize;

// This step only plans. Building the list first, and walking it
// second, is what lets the Sub Process run the pages in parallel.
var pages = new List<PageInfo>();
for (int start = 0; start < Input.total; start += size)
    pages.Add(new PageInfo() { number = pages.Count + 1, startIndex = start, size = size });

Logger.LogInformation($"{Input.total} rows split into {pages.Count} pages of {size}");
return pages;

// Inside the loop Input is ONE element of the list, not the list.
var page = (PageInfo)Input;

// Parameters here belong to the Sub Process; the outer scope is Root.
var url = $"{Root.Parameters.config.listUrl}?_start={page.startIndex}&_limit={page.size}";
Logger.LogInformation($"page {page.number} would read {url}, pass {Transition.Counter}");
return page;

